<?php $posts=$d['recentPosts']; $statusColors=['xuat_ban'=>'success','cho_duyet'=>'warning','tu_choi'=>'danger','an'=>'secondary','nhap'=>'info','da_ban'=>'dark']; ?>
<div class="card border-0 shadow-sm" id="recent-posts"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h6 fw-bold mb-0">Tin đăng gần đây</h2><span class="text-muted small">Tối đa 10 tin mới nhất</span></div><div class="table-responsive"><table class="table align-middle dashboard-table"><thead><tr><th>Tin đăng</th><th>Giá</th><th>Ngày đăng</th><th>Trạng thái</th><th class="text-end">Thao tác</th></tr></thead><tbody>
<?php if(!$posts): ?><tr><td colspan="5" class="text-center text-muted py-4">Bạn chưa có tin đăng.</td></tr><?php endif; ?>
<?php foreach($posts as $post): ?><tr><td><div class="d-flex align-items-center gap-2"><img loading="lazy" class="dashboard-post-thumb" src="<?= htmlspecialchars(img_url($post['image']),ENT_QUOTES,'UTF-8') ?>" alt=""><div><div class="fw-semibold dashboard-post-title"><?= htmlspecialchars($post['title'],ENT_QUOTES,'UTF-8') ?></div><?php if($post['vip_level']>0): ?><span class="badge text-bg-warning">VIP <?= $post['vip_level'] ?></span><?php endif; ?><?php if($post['rejection_reason']): ?><div class="small text-danger"><?= htmlspecialchars($post['rejection_reason'],ENT_QUOTES,'UTF-8') ?></div><?php endif; ?></div></div></td><td class="fw-semibold text-danger"><?= is_numeric($post['price'])?number_format((float)$post['price']).' đ':htmlspecialchars($post['price']) ?></td><td><?= date('d/m/Y',strtotime($post['created_at'])) ?></td><td><span class="badge text-bg-<?= $statusColors[$post['status']]??'secondary' ?>"><?= htmlspecialchars($post['status_label']) ?></span></td><td class="text-end"><div class="d-flex flex-wrap justify-content-end gap-1"><a class="btn btn-sm btn-outline-primary" href="<?= URL_ROOT ?>/nguoi-dung/editPost/<?= $post['id'] ?>" title="Sửa"><i class="fa-solid fa-pen"></i></a><?php if($post['vip_level']>0): ?><form method="POST" action="<?= URL_ROOT ?>/nguoi-dung/renewVipPost" class="d-inline"><?= Csrf::field() ?><input type="hidden" name="project_id" value="<?= $post['id'] ?>"><input type="hidden" name="days" value="7"><button class="btn btn-sm btn-outline-warning" title="Gia hạn VIP 7 ngày"><i class="fa-solid fa-clock-rotate-left"></i></button></form><?php endif; ?><form method="POST" action="<?= URL_ROOT ?>/nguoi-dung/dashboard/hide-post/<?= $post['id'] ?>" class="d-inline"><?= Csrf::field() ?><button class="btn btn-sm btn-outline-secondary" title="Ẩn"><i class="fa-solid fa-eye-slash"></i></button></form><form method="POST" action="<?= URL_ROOT ?>/nguoi-dung/dashboard/delete-post/<?= $post['id'] ?>" class="d-inline dashboard-delete-form"><?= Csrf::field() ?><button class="btn btn-sm btn-outline-danger" title="Xóa"><i class="fa-solid fa-trash"></i></button></form></div></td></tr><?php endforeach; ?>
</tbody></table></div></div></div>
